package cn.cloudcurtain.tv;

import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;
import androidx.media3.exoplayer.ExoPlayer;import androidx.media3.common.Player;
import java.io.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;

/** Two separate processes prove encrypted history survives restart and resumes a fresh cloud URL. */
final class HistoryLiveCheck {
    static void cloudSources(Instrumentation test,Bundle result)throws Exception{
        List<MovieLibrary.Movie> movies=new MovieLibrary(test.getTargetContext()).movies();
        for(Provider provider:Provider.values()){
            result.putString("source_stage",provider.name());MovieLibrary.Movie chosen=null;
            for(MovieLibrary.Movie movie:movies)if(movie.provider==provider&&!movie.personal){chosen=movie;break;}
            require(chosen!=null,"History reference source missing");MediaSpec ref=new MediaSpec("",chosen.name).inFolder(chosen.folder,chosen.parents);ref.provider=provider.name();ref.key=chosen.playbackKey();ref.space=chosen.space;ref.sourceBytes=chosen.size;
            PlaybackHistory.Entry saved=PlaybackHistory.snapshot(ref,60000,0,false,1);MediaSpec fresh=PlaybackHistory.resolve(saved);require(fresh.key.equals(ref.key)&&fresh.folder.equals(ref.folder)&&UrlRules.isWeb(fresh.url),"Fresh history source identity differs");
            try(okhttp3.Response response=Net.client(fresh).newCall(new okhttp3.Request.Builder().url(fresh.url).header("Range","bytes=0-4095").build()).execute()){result.putInt(provider.name()+"_http",response.code());require(response.isSuccessful()&&response.peekBody(4096).bytes().length>0,"Fresh history source cannot be read");}
            result.putBoolean(provider.name()+"_fresh_reference",true);
        }
    }
    private static Field field(Class<?> type,String name)throws Exception{Field f=type.getDeclaredField(name);f.setAccessible(true);return f;}
    private static void require(boolean condition,String message)throws IOException{if(!condition)throw new IOException(message);}
    private static File backup(Context context){return new File(context.getCacheDir(),"history-check-backup.json");}
    private static String key(MovieLibrary.Movie movie){return Integer.toHexString(movie.playbackKey().hashCode());}
    private static void drain()throws Exception{PlaybackHistory.IO.submit(()->{}).get(15,java.util.concurrent.TimeUnit.SECONDS);}
    private static void begin(Context context,MovieLibrary.Movie movie)throws Exception{
        drain();JSONObject saved=new JSONObject().put("history",new JSONObject(context.getSharedPreferences("playback_history",0).getAll())).put("progress",new JSONObject()).put("pid",android.os.Process.myPid());
        JSONObject progress=saved.getJSONObject("progress");android.content.SharedPreferences prefs=context.getSharedPreferences("progress",0);for(String name:new String[]{key(movie),"quality:"+key(movie),"compatible:"+key(movie)})progress.put(name,prefs.contains(name)?prefs.getAll().get(name):JSONObject.NULL);
        try(FileOutputStream out=new FileOutputStream(backup(context))){out.write(saved.toString().getBytes(StandardCharsets.UTF_8));}
        new PlaybackHistory(context).clear();prefs.edit().putLong(key(movie),0).putString("quality:"+key(movie),"baidu:1080").putBoolean("compatible:"+key(movie),true).commit();
    }
    private static void restore(Context context)throws Exception{
        drain();File file=backup(context);if(!file.exists())return;JSONObject saved=new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));
        android.content.SharedPreferences.Editor history=context.getSharedPreferences("playback_history",0).edit().clear();JSONObject values=saved.getJSONObject("history");for(Iterator<String> i=values.keys();i.hasNext();){String name=i.next();history.putString(name,values.getString(name));}history.commit();
        android.content.SharedPreferences.Editor edit=context.getSharedPreferences("progress",0).edit();JSONObject progress=saved.getJSONObject("progress");for(Iterator<String> i=progress.keys();i.hasNext();){String name=i.next();Object value=progress.get(name);if(value==JSONObject.NULL)edit.remove(name);else if(value instanceof Boolean)edit.putBoolean(name,(Boolean)value);else if(value instanceof Number)edit.putLong(name,((Number)value).longValue());else edit.putString(name,value.toString());}edit.commit();
        String fixtureKey=Integer.toHexString(new File(context.getCacheDir(),"history-fixture.mkv").toURI().toString().hashCode());context.getSharedPreferences("progress",0).edit().remove(fixtureKey).commit();
        if(!file.delete())throw new IOException("History fixture backup cleanup failed");
    }
    private static PlaybackHistory.Entry entry(Context context,String key)throws Exception{for(PlaybackHistory.Entry entry:new PlaybackHistory(context).entries())if(entry.source.key.equals(key))return entry;return null;}
    private static void ready(Instrumentation test,PlayerActivity activity,long position)throws Exception{
        long until=SystemClock.elapsedRealtime()+60000;boolean[] done={false};do{Thread.sleep(150);test.runOnMainSync(()->{try{ExoPlayer player=(ExoPlayer)field(PlayerActivity.class,"player").get(activity);done[0]=activity.hasWindowFocus()&&field(PlayerActivity.class,"firstFrame").getBoolean(activity)&&player!=null&&player.isPlaying()&&player.getCurrentPosition()>=position;}catch(Exception e){throw new RuntimeException(e);}});}while(!done[0]&&SystemClock.elapsedRealtime()<until);require(done[0],"History video did not render at requested position");test.waitForIdleSync();
    }
    private static View card(Instrumentation test,MainActivity home,String id)throws Exception{
        long until=SystemClock.elapsedRealtime()+15000;View[] found={null};do{Thread.sleep(100);test.runOnMainSync(()->{View v=home.findViewById(android.R.id.content).findViewWithTag("history:"+id);found[0]=home.hasWindowFocus()&&v!=null&&v.getWidth()>0?v:null;});}while(found[0]==null&&SystemClock.elapsedRealtime()<until);require(found[0]!=null,"Homepage history card missing");test.waitForIdleSync();Thread.sleep(250);return found[0];
    }
    private static void close(Instrumentation test,Activity activity)throws Exception{if(activity!=null&&!activity.isFinishing()){test.runOnMainSync(activity::finish);test.waitForIdleSync();}}
    private static Activity openByRemote(Instrumentation test,String type)throws Exception{Instrumentation.ActivityMonitor monitor=test.addMonitor(type,null,false);try{test.sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);Activity activity=monitor.waitForActivityWithTimeout(60000);require(activity!=null,"History click did not open activity");return activity;}finally{test.removeMonitor(monitor);}}
    static void record(Instrumentation test,Bundle result)throws Exception{
        Context context=test.getTargetContext();MovieLibrary.Movie movie=BaiduBufferLiveCheck.chosen(test,"878005e");begin(context,movie);PlayerActivity player=null;MainActivity home=null;boolean success=false;
        try{
            home=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));MainActivity main=home;Thread.sleep(300);boolean[] empty={false};test.runOnMainSync(()->empty[0]=main.findViewById(android.R.id.content).findViewWithTag("home_history").getVisibility()==View.GONE);require(empty[0],"Empty homepage history is not hidden");result.putBoolean("empty_home_history",true);
            MediaSpec media=new MovieLibrary(context).resolve(movie,true);player=(PlayerActivity)test.startActivitySync(new Intent(context,PlayerActivity.class).putExtra("media",media.json()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready(test,player,1000);PlayerActivity current=player;
            test.runOnMainSync(()->{try{((ExoPlayer)field(PlayerActivity.class,"player").get(current)).seekTo(300000);}catch(Exception e){throw new RuntimeException(e);}});ready(test,player,300000);
            long until=SystemClock.elapsedRealtime()+20000;PlaybackHistory.Entry saved;do{Thread.sleep(250);saved=entry(context,movie.playbackKey());}while((saved==null||saved.position<300000)&&SystemClock.elapsedRealtime()<until);require(saved!=null&&saved.position>=300000,"Periodic history checkpoint missing");result.putBoolean("periodic_progress_saved",true);
            close(test,player);player=null;drain();saved=entry(context,movie.playbackKey());require(saved!=null&&saved.source.url.isEmpty()&&saved.source.headers.isEmpty(),"History contains stale signed cloud source");result.putBoolean("cloud_reference_without_signed_url",true);
            View visible=card(test,home,saved.id());boolean[] complete={false};test.runOnMainSync(()->{android.graphics.Rect bounds=new android.graphics.Rect();complete[0]=visible.getGlobalVisibleRect(bounds)&&bounds.height()==visible.getHeight();});require(complete[0],"Recent card is clipped below the homepage fold");result.putBoolean("home_history_visible_without_scroll",true);Thread.sleep(600);android.graphics.Bitmap image=test.getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(context.getCacheDir(),"home-history.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}
            String ciphertext=context.getSharedPreferences("playback_history",0).getString("items","");require(!ciphertext.isEmpty()&&!ciphertext.contains(movie.id)&&!ciphertext.contains(movie.name)&&!ciphertext.contains("position"),"History is not encrypted at rest");result.putBoolean("history_encrypted_at_rest",true);result.putLong("recorded_position_ms",saved.position);success=true;
        }finally{close(test,player);close(test,home);drain();if(!success)restore(context);}
    }
    static void resume(Instrumentation test,Bundle result)throws Exception{
        Context context=test.getTargetContext();MovieLibrary.Movie movie=BaiduBufferLiveCheck.chosen(test,"878005e");MainActivity home=null;HistoryActivity all=null;PlayerActivity player=null;
        try{
            JSONObject backup=new JSONObject(new String(java.nio.file.Files.readAllBytes(backup(context).toPath()),StandardCharsets.UTF_8));require(backup.getInt("pid")!=android.os.Process.myPid(),"Test must restart application between phases");result.putBoolean("separate_process_restart",true);
            PlaybackHistory.Entry saved=entry(context,movie.playbackKey());require(saved!=null&&saved.position>=300000,"Saved history lost across restart");context.getSharedPreferences("progress",0).edit().putLong(key(movie),0).commit();
            home=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));MainActivity main=home;View recent=card(test,home,saved.id());test.runOnMainSync(()->main.findViewById(android.R.id.content).findViewWithTag("home_history_all").requestFocus());test.sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);boolean[] focused={false};test.runOnMainSync(()->focused[0]=main.getCurrentFocus()==recent);require(focused[0],"Recent card not reachable from home actions with DPAD");result.putBoolean("home_remote_focus",true);
            player=(PlayerActivity)openByRemote(test,PlayerActivity.class.getName());ready(test,player,saved.position);PlayerActivity current=player;long[] at={0};test.runOnMainSync(()->{try{at[0]=((ExoPlayer)field(PlayerActivity.class,"player").get(current)).getCurrentPosition();MediaSpec fresh=(MediaSpec)field(PlayerActivity.class,"media").get(current);result.putBoolean("fresh_cloud_url_and_folder",UrlRules.isWeb(fresh.url)&&fresh.folder.equals(movie.folder)&&fresh.key.equals(movie.playbackKey()));}catch(Exception e){throw new RuntimeException(e);}});require(at[0]<saved.position+30000&&result.getBoolean("fresh_cloud_url_and_folder"),"History did not restore the saved position using a fresh source");result.putLong("resumed_position_ms",at[0]);result.putBoolean("home_click_resumes",true);
            long until=SystemClock.elapsedRealtime()+15000;while(field(PlayerActivity.class,"episodes").get(player)==null&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);require(field(PlayerActivity.class,"episodes").get(player)!=null,"History resume lost episode folder");result.putBoolean("episode_navigation_context_retained",true);
            close(test,player);player=null;drain();card(test,home,saved.id());test.runOnMainSync(()->main.findViewById(android.R.id.content).findViewWithTag("home_history_all").requestFocus());all=(HistoryActivity)openByRemote(test,HistoryActivity.class.getName());HistoryActivity history=all;
            until=SystemClock.elapsedRealtime()+10000;View[] row={null};do{Thread.sleep(100);test.runOnMainSync(()->{View view=history.findViewById(android.R.id.content).findViewWithTag("history:"+saved.id());row[0]=history.hasWindowFocus()&&view!=null&&view.getWidth()>0?view:null;});}while(row[0]==null&&SystemClock.elapsedRealtime()<until);require(row[0]!=null,"All-history entry missing");test.waitForIdleSync();Thread.sleep(250);test.runOnMainSync(()->row[0].requestFocus());test.sendKeyDownUpSync(KeyEvent.KEYCODE_MENU);Thread.sleep(200);
            List<AccessibilityNodeInfo> remove=Collections.emptyList();until=SystemClock.elapsedRealtime()+8000;do{Thread.sleep(200);AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();remove=root==null?Collections.emptyList():root.findAccessibilityNodeInfosByText("移除记录");}while(remove.isEmpty()&&SystemClock.elapsedRealtime()<until);result.putBoolean("history_actions_visible",!remove.isEmpty());require(!remove.isEmpty(),"Remote menu did not expose history actions");test.sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);test.sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);test.sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);
            until=SystemClock.elapsedRealtime()+10000;while(entry(context,movie.playbackKey())!=null&&SystemClock.elapsedRealtime()<until)Thread.sleep(150);require(entry(context,movie.playbackKey())==null,"Removed history reappeared");result.putBoolean("remote_menu_remove",true);close(test,all);all=null;Thread.sleep(300);
            File fixture=new File(context.getCacheDir(),"history-fixture.mkv");try(InputStream input=test.getContext().getAssets().open("subtitle-fixture.mkv");FileOutputStream output=new FileOutputStream(fixture)){byte[] buffer=new byte[16384];int n;while((n=input.read(buffer))!=-1)output.write(buffer,0,n);}
            MediaSpec local=new MediaSpec(fixture.toURI().toString(),"历史本地测试.mkv");player=(PlayerActivity)test.startActivitySync(new Intent(context,PlayerActivity.class).putExtra("media",local.json()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready(test,player,1000);PlayerActivity localPlayer=player;test.runOnMainSync(()->{try{ExoPlayer p=(ExoPlayer)field(PlayerActivity.class,"player").get(localPlayer);p.seekTo(p.getDuration()-200);}catch(Exception e){throw new RuntimeException(e);}});
            PlaybackHistory.Entry completed=null;until=SystemClock.elapsedRealtime()+15000;do{Thread.sleep(150);completed=entry(context,local.key);}while((completed==null||!completed.completed)&&SystemClock.elapsedRealtime()<until);require(completed!=null&&completed.completed&&completed.resumePosition()==0,"Completed local entry does not restart from zero");result.putBoolean("local_completed_history",true);close(test,player);player=null;drain();new PlaybackHistory(context).clear();require(new PlaybackHistory(context).entries().isEmpty(),"Clear history failed");result.putBoolean("clear_stays_empty",true);
        }finally{close(test,player);close(test,all);close(test,home);restore(context);}
    }
}
